import * as THREE from 'three';
import {canMove} from '../physics.js';
import {autoFitOrthographicBounds} from '../camera-fit.js';
import {createLaserRig} from './laser-rig.js';
const DT=1/120,smooth=t=>t*t*(3-2*t),sign=s=>s==='left'?-1:1,copy=x=>structuredClone(x);
/** One original actor owner, supported stationary toy-light entry, and no independent clock. */
export function createLaserSession({view,player,model,poser,rigFactory=createLaserRig}){
 const laser=view?.schoolView?.gymView?.laser,machine=laser?.machine;if(!machine||!player||!model||!poser)throw Error('Laser station unavailable');if(view.gymSession)throw Error('Gym station already owned');
 const saved={parent:player.parent,p:player.position.clone(),q:player.quaternion.clone(),s:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),children:player.children.map(n=>[n,n.visible]),fixtures:[]};laser.machine.traverse(n=>saved.fixtures.push({n,p:n.position.clone(),q:n.quaternion.clone(),s:n.scale.clone(),visible:n.visible}));
 machine.updateWorldMatrix(true,true);const origin=machine.worldToLocal(player.getWorldPosition(new THREE.Vector3())),path=[{x:origin.x,z:origin.z},{x:0,z:-2},{x:0,z:0}],world=view.residents?.collisionWorld?.()??{bounds:{minX:-16,maxX:16,minZ:-16,maxZ:16},obstacles:[]};
 for(let j=1;j<path.length;j++){const a=path[j-1],b=path[j],n=Math.max(1,Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/.04));for(let i=0;i<=n;i++){const p=machine.localToWorld(new THREE.Vector3(a.x+(b.x-a.x)*i/n,0,a.z+(b.z-a.z)*i/n));view.root.worldToLocal(p);if(!canMove(world,p.x,p.z,.66))throw Error('Laser approach blocked');}}
 let alive=true,rig,phase='boarding',exitRequested=false,queue=[],op=null,accumulator=0,guardTime=0,guardStart=0;
 let frame={root:{x:origin.x,y:.012,z:origin.z},feet:{left:{x:origin.x-.21,y:.012,z:origin.z,contact:true},right:{x:origin.x+.21,y:.012,z:origin.z,contact:true}},guard:0,yaw:.025,pitch:.035,targets:null,beam:null};const token={};
 function route(a,b){const n=Math.max(1,Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/.30));for(let i=1;i<=n;i++)for(const side of['left','right'])queue.push({side,target:{x:a.x+(b.x-a.x)*i/n+sign(side)*.21,y:.012,z:a.z+(b.z-a.z)*i/n,contact:true},ticks:30});}
 function apply(){const p=machine.localToWorld(new THREE.Vector3(frame.root.x,frame.root.y,frame.root.z));if(player.parent)player.parent.worldToLocal(p);player.position.copy(p);const q=machine.getWorldQuaternion(new THREE.Quaternion());if(player.parent)q.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(q);rig.apply(frame);if(frame.guard>=.999)laser.setDevice(rig.fit(frame));else laser.setDevice(null);player.updateWorldMatrix(true,true);}
 function exitRoute(){queue=[];op=null;phase='exiting';const center={x:(frame.feet.left.x+frame.feet.right.x)/2,z:(frame.feet.left.z+frame.feet.right.z)/2};for(const side of['left','right'])queue.push({side,target:{x:center.x+sign(side)*.21,y:.012,z:center.z,contact:true},ticks:30});route(center,path[1]);route(path[1],path[0]);}
 function lowerGuard(){phase='lowering';guardTime=0;guardStart=frame.guard??1;frame.beam=null;}
 function transfer(){if(!op){if(exitRequested&&phase==='boarding'){exitRoute();return;}if(!queue.length){if(phase==='exiting')phase='done';else{phase='guarding';guardTime=0;}return;}const next=queue.shift();op={...next,t:0,start:copy(frame.feet[next.side]),root:{...frame.root},other:copy(frame.feet[next.side==='left'?'right':'left'])};}
  op.t++;const t=Math.min(1,op.t/op.ticks),u=smooth(t),f=frame.feet[op.side];for(const a of['x','y','z'])f[a]=op.start[a]+(op.target[a]-op.start[a])*u;f.y+=.08*Math.sin(Math.PI*t);f.contact=t===1;for(const a of['x','y','z']){const end=(op.target[a]+op.other[a])/2;frame.root[a]=op.root[a]+(end-op.root[a])*u;}frame.root.y+=.008*Math.sin(Math.PI*t)**2;if(t===1){frame.feet[op.side]=copy(op.target);op=null;if(exitRequested&&phase==='boarding')exitRoute();}}
 function step(){if(phase==='boarding'||phase==='exiting')transfer();else if(phase==='guarding'){if(exitRequested){lowerGuard();return;}guardTime++;frame.guard=smooth(Math.min(1,guardTime/42));if(guardTime>=42)phase='ready';}else if(phase==='lowering'){guardTime++;frame.guard=guardStart*(1-smooth(Math.min(1,guardTime/42)));if(guardTime>=42)exitRoute();}}
 function tick(dt,practice){if(alive&&view.gymSession!==token){dispose({restore:false});phase='done';return;}if(!alive||!practice||practice.snapshot().paused||!Number.isFinite(dt)||dt<=0)return;
  if(['ready','exercise'].includes(phase)){
   const s=practice.snapshot();if(['active','stopping'].includes(s.state)){phase='exercise';practice.update(dt,{prepare(f){laser.setTargets(f.targets);laser.setDevice(rig.fit(f));},fire(f){rig.apply(f);laser.setDevice(rig.fit(f));return rig.probe(f,laser);},ray:laser.ray});frame=copy(practice.snapshot().frame);if(practice.snapshot().state==='stopped')phase='ready';}
   if(exitRequested&&phase==='ready')lowerGuard();apply();return;
  }
  accumulator+=Math.min(dt,.1);let n=Math.floor((accumulator+1e-10)/DT);accumulator=Math.max(0,accumulator-n*DT);const had=n>0;while(n--&&phase!=='done')step();if(had)apply();
 }
 function requestExit(){if(!alive||exitRequested)return;exitRequested=true;if(phase==='ready')lowerGuard();}
 function dispose({restore=true}={}){if(!alive)return;alive=false;const owned=view.gymSession===token;if(owned)delete view.gymSession;rig?.release({restore:restore&&owned});if(!restore||!owned)return;for(const r of saved.fixtures){r.n.position.copy(r.p);r.n.quaternion.copy(r.q);r.n.scale.copy(r.s);r.n.visible=r.visible;}laser.machine.updateWorldMatrix(true,true);if(player.parent!==saved.parent){if(saved.parent)saved.parent.add(player);else player.removeFromParent();}player.position.copy(saved.p);player.quaternion.copy(saved.q);player.scale.copy(saved.s);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);for(const[n,v]of saved.children)n.visible=v;player.updateWorldMatrix(true,true);}
 try{view.gymSession=token;model.position.set(0,0,0);model.quaternion.identity();for(const[n]of saved.children)if(n!==model)n.visible=false;rig=rigFactory({model,poser});laser.setDevice(null);route(path[0],path[1]);route(path[1],path[2]);apply();}catch(error){dispose();throw error;}
 return{tick,requestExit,dispose,pause(){accumulator=0;},get root(){return machine;},get ready(){return phase==='ready';},get done(){return phase==='done';},get phase(){return phase;},snapshot:()=>({phase,exitRequested,frame:copy(frame),actorUUID:model.uuid,scale:model.scale.toArray()})};
}
export function fitLaserCamera(camera,machine,viewport,{active=false}={}){machine.updateWorldMatrix(true,false);camera.position.set(-3.2,3.1,3.0);camera.quaternion.identity();camera.up.set(0,1,0);camera.lookAt(new THREE.Vector3(0,.85,1.9));camera.updateMatrixWorld(true);const bounds=new THREE.Box3(new THREE.Vector3(-1.63,0,active?-.4:-3.35),new THREE.Vector3(1.63,2.15,active?5.68:1.1));autoFitOrthographicBounds({camera,worldBounds:bounds,viewport,paddingPx:{left:12,right:12,top:12,bottom:12}});camera.applyMatrix4(machine.matrixWorld);camera.updateMatrixWorld(true);return bounds.applyMatrix4(machine.matrixWorld);}
